-- koloni-285: Tekman Arılığı iğnesi ilçe merkezinden (39.645, 41.5083) en iyi foraj noktasına: Düzyurt doğusu yayla merası 39.675, 41.404 (~2155 m).
-- Kaynaklar yalnız yönetici panelinde (Kural kaynakları › Arılık konumu); kullanıcı sayfasında gösterilmez.
-- Canlı veri: apiaries.data lat/lon güncellemesi yönetim API ile uygulandı (yedek alındı); bu dosya kaynak satırı + Yapılacaklar.
insert into public.kural_kaynaklari (id,grup,sira,ad,degerler,seviye,aciklama,kaynak,durum) values
('konum_tekman','arılık konumu',10,'Tekman Arılığı: foraj konumu','39.675, 41.404 · ~2155 m · Düzyurt köyünün ~2,2 km doğusu','bilgi',
 'İlçe merkezi yerine ilçe sınırı (OSM rel. 1832940) içinde ~400 m ızgara tarandı. Seçilen nokta: CORINE 321 doğal çayır içinde; 2,5 km uçuş yarıçapında %82 doğal çayır (321) + %5 mera (231) + %5 karışık tarım-doğal alan (243), %0 ekili tarla (211/212/242 → ilaç riski düşük), %7 seyrek bitki (333), %1 yerleşim; ESA WorldCover 2 km içinde %97 çayır, %2 ekili alan; eğim ~1°; dere ~430 m; tali yol (tertiary) ~540 m; en yakın köy Düzyurt ~2,2 km; Geçit (~1000 kovanlı yerel arıcı) ~6 km kuzeyde. Uygulamanın foraj modeli bu noktada öneri (taşı) çıkarmıyor.',
 'Ağırlıklar, eşikler (köy ≥1,5 km, su ≤0,5 km, yol ≤1 km, 1950–2300 m, eğim) ve rakip arılık mesafesi: uzman tahmini. Arazi örtüsü: CORINE Land Cover 2018 (EEA, Copernicus); ESA WorldCover 10 m 2021 v200. Rakım/eğim: Copernicus DEM GLO-30. Su/yol/köy: OpenStreetMap (Overpass, 18.10.2026). Flora ve dönem: Cınbırtoğlu (haz.), İl ve İlçelere Göre Çiçeklenme Dönemi, TAGEM Ordu Arıcılık Araştırma Enstitüsü 2022 — Erzurum/Tekman Haziran–Ağustos; yonca, kekik, civan perçemi, adaçayı, korunga, üçgül, taş yoncası, geven. Bölgenin arıcılık uygunluğu: «Tekman''da Arıcılığı Geliştirme Projesi» (AB destekli, Erzurum Erzincan Bayburt Kalkınma Birliği, 2007; Geçit, Düzyurt, Taşkesen, Erence köyleri; Erzurum Gazetesi); Atatürk Üniv. Ziraat Fak. + Erzurum Arı Yetiştiricileri Birliği uygulamalı eğitimi Geçit köyünde (Erzurum Gazetesi); Erzurum İl Tarım ve Orman Md.: geniş çayır-mera, kimyasal kullanımı sıfıra yakın. Yerinde flora sayımı yok.',
 'uzman tahmini')
on conflict (id) do update set degerler=excluded.degerler, seviye=excluded.seviye, aciklama=excluded.aciklama, kaynak=excluded.kaynak, durum=excluded.durum, updated_at=now();
insert into public.yapilacaklar (baslik, aciklama)
select v.b, v.a from (values
 ('Tekman Arılığı konumu (39.675, 41.404) yerinde doğrulanmalı (uzman tahmini)','Uydu arazi örtüsü + OSM ile seçildi; yerinde flora (korunga, üçgül, geven, kekik yoğunluğu), dere suyunun yaz boyu akışı, araç yolu durumu, mera sahibi/muhtar izni ve yakın gezginci arılıklar kontrol edilmeli. Yönetici › Kural kaynakları › Arılık konumu.')
) as v(b,a) where not exists (select 1 from public.yapilacaklar y where y.baslik = v.b);
